"use client";

import * as React from "react";
import { Price, PricingToggle } from "./pricing-toggle";

/* ─────────────────────────────────────────────────────────
 * COMPARISON TABLE: plans side by side, and one that stands out
 *
 *   rest      the recommended plan sits in a thin line column that
 *             runs the height of the table
 *   point     move across the table and the column glides to the
 *             plan under you with a little give, then settles
 *             back when you leave
 *   billing   Monthly/Yearly is thrown to the choice and every
 *             price rolls; the note under it slides the same way
 *   groups    each section folds open and shut to its height
 *   phone     one plan at a time: a switch is thrown to the plan
 *             and its column slides in from the side you went
 *
 * Header stays at the top while the features scroll past.
 * ───────────────────────────────────────────────────────── */

export interface ComparisonPlan {
  id: string;
  name: string;
  /** Monthly price, or { monthly, yearly } per month; null for "Custom". */
  price: number | { monthly: number; yearly: number } | null;
  description?: string;
  /** The column that's highlighted at rest. */
  featured?: boolean;
  badge?: string;
  cta?: { label: string; href?: string; onClick?: () => void };
}

export type ComparisonValue = boolean | string | number | null | undefined;

export interface ComparisonRow {
  label: string;
  hint?: string;
  values: Record<string, ComparisonValue>;
}

export interface ComparisonGroup {
  title: string;
  rows: ComparisonRow[];
  /** Start folded. */
  collapsed?: boolean;
}

export interface ComparisonTableProps extends React.HTMLAttributes<HTMLDivElement> {
  plans: ComparisonPlan[];
  groups: ComparisonGroup[];
  currency?: string;
  /** Shows a Monthly/Yearly switch, e.g. "Save 20%". */
  yearlyBadge?: string;
  /** How far from the top the header sticks (e.g. under a fixed navbar). */
  stickyTop?: number;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Cell({ value }: { value: ComparisonValue }) {
  if (value === true)
    return (
      <svg
        role="img"
        aria-label="Included"
        viewBox="0 0 16 16"
        fill="none"
        className="size-4 text-foreground"
      >
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  if (value === false || value === null || value === undefined)
    return (
      <svg
        role="img"
        aria-label="Not included"
        viewBox="0 0 16 16"
        fill="none"
        className="size-4 text-muted-foreground/45"
      >
        <path
          d="M4.5 8h7"
          stroke="currentColor"
          strokeWidth="1.6"
          strokeLinecap="round"
        />
      </svg>
    );
  return <span className="text-[13px] text-foreground">{value}</span>;
}

export function ComparisonTable({
  plans,
  groups,
  currency = "USD",
  yearlyBadge,
  stickyTop = 0,
  className = "",
  ...props
}: ComparisonTableProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [billing, setBilling] = React.useState("monthly");
  const [billingDir, setBillingDir] = React.useState(1);
  const [hover, setHover] = React.useState<number | null>(null);
  const [selected, setSelected] = React.useState(() =>
    Math.max(
      0,
      plans.findIndex((p) => p.featured),
    ),
  );
  const [dir, setDir] = React.useState(1);
  const [open, setOpen] = React.useState(() => groups.map((g) => !g.collapsed));
  const [cols, setCols] = React.useState<{ left: number; width: number }[]>([]);
  const [ready, setReady] = React.useState(false);
  const headRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const headerRef = React.useRef<HTMLDivElement>(null);
  const [headerHeight, setHeaderHeight] = React.useState(0);
  const switchRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0 });

  const featured = plans.findIndex((p) => p.featured);
  const lit = hover ?? (featured >= 0 ? featured : null);
  const template = `minmax(9.5rem,1.35fr) repeat(${plans.length}, minmax(0,1fr))`;

  // Where each plan's column is, so the highlight can glide between them.
  React.useLayoutEffect(() => {
    const measure = () => {
      const next = headRefs.current.map((el) => ({
        left: el?.offsetLeft ?? 0,
        width: el?.offsetWidth ?? 0,
      }));
      setCols((c) =>
        c.length === next.length &&
        c.every((x, i) => x.left === next[i].left && x.width === next[i].width)
          ? c
          : next,
      );
      setHeaderHeight((h) =>
        h === headerRef.current?.offsetHeight
          ? h
          : (headerRef.current?.offsetHeight ?? 0),
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    headRefs.current.forEach((el) => el && observer.observe(el));
    if (headerRef.current) observer.observe(headerRef.current);
    const frame = requestAnimationFrame(() => setReady(true));
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [plans.length]);

  // The phone switch's thumb.
  React.useLayoutEffect(() => {
    const el = switchRefs.current[selected];
    if (el)
      setThumb((t) =>
        t.left === el.offsetLeft && t.width === el.offsetWidth
          ? t
          : { left: el.offsetLeft, width: el.offsetWidth },
      );
  }, [selected, plans.length]);

  const pick = (i: number) => {
    setDir(i >= selected ? 1 : -1);
    setSelected(i);
  };

  const onMove = (e: React.PointerEvent) => {
    if (e.pointerType === "touch") return;
    const x =
      e.clientX - (e.currentTarget as HTMLElement).getBoundingClientRect().left;
    const i = cols.findIndex(
      (c) => x >= c.left - 6 && x <= c.left + c.width + 6,
    );
    setHover(i >= 0 ? i : null);
  };

  const column = lit !== null ? cols[lit] : undefined;
  const glide =
    ready && !reduced
      ? `transform 520ms ${THROW}, width 420ms ${EASE}, opacity 300ms ${EASE}`
      : "none";
  // On a phone only the chosen plan shows; it slides in from the side you went.
  const phone = (i: number) =>
    i === selected
      ? `@max-[36rem]:block ${dir > 0 ? "@max-[36rem]:animate-[ui-slide-from-right_360ms_cubic-bezier(0.16,1,0.3,1)_both]" : "@max-[36rem]:animate-[ui-slide-from-left_360ms_cubic-bezier(0.16,1,0.3,1)_both]"} motion-reduce:animate-none`
      : "@max-[36rem]:hidden";

  const priceOf = (plan: ComparisonPlan) =>
    plan.price === null
      ? null
      : typeof plan.price === "number"
        ? plan.price
        : billing === "yearly"
          ? plan.price.yearly
          : plan.price.monthly;

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 880px)" }}
      />
      <div className="@container w-full">
        <div className={`w-full ${className}`} {...props}>
          <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
            {yearlyBadge && (
              <PricingToggle
                value={billing}
                onValueChange={(v) => {
                  setBillingDir(v === "yearly" ? 1 : -1);
                  setBilling(v);
                }}
                options={[
                  { value: "monthly", label: "Monthly" },
                  { value: "yearly", label: "Yearly", badge: yearlyBadge },
                ]}
              />
            )}
            {/* Phones: one plan at a time. */}
            <div
              role="tablist"
              aria-label="Plan"
              className="relative inline-flex rounded-full bg-muted p-0.5 @[36rem]:hidden"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: thumb.width,
                  transform: `translateX(${thumb.left}px)`,
                  transition:
                    thumb.width && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {plans.map((p, i) => (
                <button
                  key={p.id}
                  ref={(el) => {
                    switchRefs.current[i] = el;
                  }}
                  type="button"
                  role="tab"
                  aria-selected={i === selected}
                  onClick={() => pick(i)}
                  className={`cursor-pointer relative h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors duration-300 ${FOCUS} ${i === selected ? "text-foreground" : "text-muted-foreground"}`}
                >
                  {p.name}
                </button>
              ))}
            </div>
          </div>

          <div
            role="table"
            aria-label="Plan comparison"
            className="relative"
            onPointerMove={onMove}
            onPointerLeave={() => setHover(null)}
          >
            {/* The column that runs the height of the table and glides between plans: this part under the header… */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute bottom-0 left-0 hidden rounded-b-[18px] bg-accent/60 shadow-[inset_1px_0_0_0_var(--border),inset_-1px_0_0_0_var(--border),inset_0_-1px_0_0_var(--border)] @[36rem]:block"
              style={{
                top: headerHeight,
                width: column?.width ?? 0,
                transform: `translateX(${column?.left ?? 0}px)`,
                opacity: column ? 1 : 0,
                transition: glide,
              }}
            />

            {/* Plan headers, kept in view while the features scroll by. */}
            <div
              ref={headerRef}
              role="rowgroup"
              className="sticky z-10 bg-background"
              style={{ top: stickyTop }}
            >
              {/* …and this part in the header, gliding in step, so the column reads as one even while the header sticks. */}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-y-0 left-0 hidden rounded-t-[18px] bg-accent/60 shadow-[inset_1px_0_0_0_var(--border),inset_-1px_0_0_0_var(--border),inset_0_1px_0_0_var(--border)] @[36rem]:block"
                style={{
                  width: column?.width ?? 0,
                  transform: `translateX(${column?.left ?? 0}px)`,
                  opacity: column ? 1 : 0,
                  transition: glide,
                }}
              />
              <div
                role="row"
                className="grid @max-[36rem]:!grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)]"
                style={{ gridTemplateColumns: template }}
              >
                <div
                  role="columnheader"
                  className="flex items-end pb-5 pr-4 text-[12px] text-muted-foreground @max-[36rem]:hidden"
                >
                  <span className="sr-only">Feature</span>
                </div>
                {plans.map((plan, i) => {
                  const amount = priceOf(plan);
                  return (
                    <div
                      key={plan.id}
                      ref={(el) => {
                        headRefs.current[i] = el;
                      }}
                      role="columnheader"
                      aria-label={plan.name}
                      className={`relative px-4 pb-5 pt-5 @max-[36rem]:col-span-2 @max-[36rem]:px-0 ${phone(i)}`}
                    >
                      <div className="relative flex items-center gap-2">
                        <span className="text-[14px] font-medium text-foreground">
                          {plan.name}
                        </span>
                        {plan.badge && (
                          <span className="rounded-full bg-primary/10 px-2 py-px text-[11px] font-medium text-primary">
                            {plan.badge}
                          </span>
                        )}
                      </div>
                      {plan.description && (
                        <p className="relative mt-1 min-h-8 text-[12px] leading-4 text-muted-foreground">
                          {plan.description}
                        </p>
                      )}
                      <div className="relative mt-3">
                        {amount === null ? (
                          <p className="text-[28px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground">
                            Custom
                          </p>
                        ) : (
                          <Price
                            amount={amount}
                            currency={currency}
                            direction={billingDir}
                            numberClassName="text-[28px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground"
                          />
                        )}
                      </div>
                      {plan.cta && (
                        <a
                          href={plan.cta.href ?? "#"}
                          onClick={(e) => {
                            if (plan.cta?.onClick) {
                              e.preventDefault();
                              plan.cta.onClick();
                            }
                          }}
                          className={`relative mt-4 flex h-9 items-center justify-center rounded-full text-[13px] font-medium transition-[background-color,color,box-shadow] duration-300 ${FOCUS} ${
                            plan.featured
                              ? "bg-primary text-primary-foreground hover:bg-primary/90"
                              : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                          }`}
                        >
                          {plan.cta.label}
                        </a>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {groups.map((group, g) => {
              const isOpen = open[g];
              const groupId = `${id}-g${g}`;
              return (
                <div key={group.title} role="rowgroup">
                  <div role="row" className="relative">
                    <div role="rowheader" className="border-t border-border">
                      <button
                        type="button"
                        aria-expanded={isOpen}
                        aria-controls={groupId}
                        onClick={() =>
                          setOpen((o) => o.map((v, i) => (i === g ? !v : v)))
                        }
                        className={`cursor-pointer flex w-full items-center gap-2 rounded-md py-3.5 text-left text-[12.5px] font-medium text-foreground ${FOCUS}`}
                      >
                        <svg
                          aria-hidden="true"
                          viewBox="0 0 12 12"
                          className="size-3 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none"
                          style={{
                            transform: isOpen ? "rotate(90deg)" : "none",
                            transitionTimingFunction: EASE,
                          }}
                        >
                          <path
                            d="m4.5 2.5 3.5 3.5-3.5 3.5"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.4"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                        </svg>
                        {group.title}
                      </button>
                    </div>
                  </div>
                  <div
                    id={groupId}
                    inert={!isOpen}
                    className="grid"
                    style={{
                      gridTemplateRows: isOpen ? "1fr" : "0fr",
                      opacity: isOpen ? 1 : 0,
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 460ms ${EASE}, opacity ${isOpen ? "360ms" : "160ms"} ${EASE}`,
                    }}
                  >
                    <div className="min-h-0 overflow-hidden">
                      {group.rows.map((row) => (
                        <div
                          key={row.label}
                          role="row"
                          className="grid border-t border-border/70 @max-[36rem]:!grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)]"
                          style={{ gridTemplateColumns: template }}
                        >
                          <div role="rowheader" className="py-3 pr-4">
                            <span className="text-[13px] text-foreground/85">
                              {row.label}
                            </span>
                            {row.hint && (
                              <span className="mt-0.5 block text-[11.5px] leading-4 text-muted-foreground">
                                {row.hint}
                              </span>
                            )}
                          </div>
                          {plans.map((plan, i) => (
                            <div
                              key={plan.id}
                              role="cell"
                              className={`relative flex items-center px-4 py-3 ${phone(i)}`}
                            >
                              <Cell value={row.values[plan.id]} />
                            </div>
                          ))}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              );
            })}
            {/* Closes the column at the bottom. */}
            <div aria-hidden="true" className="h-4 border-t border-border" />
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PRICING TOGGLE: monthly or yearly, and every price rolls
 *
 *   toggle   the thumb slides and resizes to the chosen option
 *            with a little give; the labels trade colour
 *   badge    "Save 20%" sits inside Yearly and lights up in
 *            your brand colour when it's chosen
 *   prices   Price rolls each figure to its new amount, and the
 *            billing line crossfades in the direction you went
 *
 * PricingToggle is the control; Price is the number. Use them
 * together across your plan columns.
 * ───────────────────────────────────────────────────────── */

export interface BillingOption {
  value: string;
  label: string;
  /** e.g. "Save 20%". */
  badge?: string;
}

export interface PricingToggleProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  value: string;
  onValueChange: (value: string) => void;
  options?: BillingOption[];
  label?: string;
}

export interface PriceProps extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
  currency?: string;
  /** Format in this locale everywhere. Without it, a server render and hydration use en-US and the visitor's locale takes over after mount. */
  locales?: string | string[];
  /** e.g. "/mo"; hidden for free plans. */
  period?: string;
  /** A line under the price, e.g. "$288 billed yearly". */
  note?: string;
  /** Which way the toggle moved (1 or -1), so the note slides with it. */
  direction?: number;
  /** Classes for the figure, e.g. its size. */
  numberClassName?: string;
}

const BILLING: BillingOption[] = [
  { value: "monthly", label: "Monthly" },
  { value: "yearly", label: "Yearly", badge: "Save 20%" },
];
// A little give at the end of the slide, so the thumb feels like it was thrown, not placed.
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function PricingToggle({
  value,
  onValueChange,
  options = BILLING,
  label = "Billing period",
  className = "",
  ...props
}: PricingToggleProps) {
  const reduced = useReducedMotion();
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });
  const active = Math.max(
    0,
    options.findIndex((o) => o.value === value),
  );

  React.useLayoutEffect(() => {
    const measure = () => {
      const el = refs.current[active];
      if (!el) return;
      const left = el.offsetLeft;
      const width = el.offsetWidth;
      setThumb((t) =>
        t.left === left && t.width === width
          ? t
          : { left, width, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    refs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [active, options]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    const next =
      (active + (e.key === "ArrowRight" ? 1 : -1) + options.length) %
      options.length;
    onValueChange(options[next].value);
    refs.current[next]?.focus();
  };

  return (
    <div
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative inline-flex items-center rounded-full border border-border bg-muted/60 p-1 ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="absolute inset-y-1 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          width: thumb.width,
          transform: `translateX(${thumb.left}px)`,
          transition:
            thumb.ready && !reduced
              ? `transform 520ms ${THROW}, width 420ms ${EASE}`
              : "none",
        }}
      />
      {options.map((option, i) => {
        const selected = i === active;
        return (
          <button
            key={option.value}
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            onClick={() => onValueChange(option.value)}
            className={`cursor-pointer relative flex h-8 items-center gap-2 rounded-full px-3.5 text-[13px] font-medium transition-colors duration-300 ${FOCUS} ${
              selected
                ? "text-foreground"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {option.label}
            {option.badge && (
              <span
                className={`rounded-full px-1.5 py-px text-[11px] font-medium transition-[background-color,color] duration-300 ${
                  selected
                    ? "bg-primary text-primary-foreground"
                    : "bg-primary/10 text-primary"
                }`}
              >
                {option.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function Price({
  amount,
  currency = "USD",
  locales,
  period = "/mo",
  note,
  direction = 1,
  numberClassName = "text-[40px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground",
  className = "",
  ...props
}: PriceProps) {
  const format = React.useMemo<Intl.NumberFormatOptions>(
    () => ({
      style: "currency",
      currency,
      maximumFractionDigits: amount % 1 ? 2 : 0,
      minimumFractionDigits: amount % 1 ? 2 : 0,
    }),
    [currency, amount],
  );
  return (
    <div className={className} {...props}>
      <div className="flex items-baseline gap-1">
        <NumberRoll
          value={amount}
          format={format}
          locales={locales}
          className={numberClassName}
        />
        {amount > 0 && period && (
          <span className="text-[14px] text-muted-foreground">{period}</span>
        )}
      </div>
      {note !== undefined && (
        <div className="relative mt-1 h-5 overflow-hidden text-[12.5px] text-muted-foreground">
          <span
            key={note}
            className="absolute inset-0 truncate motion-safe:animate-[ui-note-in_380ms_cubic-bezier(0.23,1,0.32,1)_both]"
            style={
              {
                "--ui-from": `${direction > 0 ? 100 : -100}%`,
              } as React.CSSProperties
            }
          >
            {note}
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

